window.RP_SESSION={"id":"S-a4900d2dc7a2","messages":[{"id":"RP-III-0022649","time":"2026-02-19T00:06:00+09:00","room":"RP III","name":"진저브레이브 / 이름 미상 여성·마을 주민","profile":"진저브레이브","identity":"reviewed","type":"dialogue","body":"————————————\n\n[\"뭐? 누굴 찾는다고?\"]\n\n(\"그러니까요 어르신..그 언데드인데..되게 저능해보이는 언데드요! 그러니까..\")\n\n[\"뭐? 사골국물을 찾는다고? 그러면 저기 골목으로 꺾어서..\"]\n\n(\"아뇨..하아..그냥 가보겠습니다..\")\n\n————————————\n\n{시끌벅적한 저녁이 지나고 한산해진 밤의 소동이 일단락되며 후드를 뒤집어쓴체 어딘가로 향하는 여인. 마을을 두리번거리거나 가게를 들락날락거리며 무언갈 찾기위해 최선을 다하며 마을을 들쑤시죠.\n\n한편 우리의 저능한 언데드인 진저는 자신의 자그마한 텃밭을 바라보며 고민에 빠져있습니다. 곧 봄이 되어가니 무엇을 키워야할지 고민중이죠. 곧 봄이니까..흠..저번에 심었던 감자나 아니면 생강을 심어볼까. 저번에 받는 70..얼마였지..그걸로 살수있을지는 모르겠지만요.}\n\n\"흠..\"\n\n{고민에 빠져있던 찰나,어김없이 모닥불을 피워보는 진저. 이번에는 누가,어떤 모습으로,어떤이야기를 가지고 찾아올지 기대가 되는 눈빛이네요.","characters":["P-11b5c9c4a5f1"]},{"id":"RP-III-0022650","time":"2026-02-19T00:11:00+09:00","room":"RP III","name":"진저브레이브 / 이름 미상 여성·마을 주민","profile":"진저브레이브","identity":"reviewed","type":"dialogue","body":"!모닥불","characters":["P-11b5c9c4a5f1"]},{"id":"RP-III-0022651","time":"2026-02-19T00:11:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"모닥불에 불씨가 옮겨 붙습니다.\n따뜻한 온기가 피어오릅니다.\n\n ♩ https://youtu.be/3GNyTB6p6i0?si=4L6Rg34M-gtWRqUj","characters":[]},{"id":"RP-III-0022652","time":"2026-02-19T12:54:00+09:00","room":"RP III","name":"레마 캐롤라인","profile":"레마 캐롤라인","identity":"unresolved","type":"dialogue","body":"-fin","characters":[]},{"id":"RP-III-0022653","time":"2026-02-19T12:54:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
